export const EMAIL_SENDER_NAME = 'Praia dos Corais | Controle de Publicadores';
export const emailSender = address => ({ name: EMAIL_SENDER_NAME, address });
export const escapeEmailHtml = value => String(value ?? '').replace(/[&<>"']/g, character => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
})[character]);

// Content is generated by the individual templates; escape their dynamic values before inserting it.
export function buildEmailHtml({ subject, preheader, label, title, content, footerNote, width = 600 }) {
  const safeWidth = width === 800 ? 800 : 600;
  return `<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>${escapeEmailHtml(subject)}</title></head>
<body style="margin:0;padding:0;background-color:#f4f3f8;font-family:Arial,Helvetica,sans-serif;color:#27272a;">
  <div style="display:none;max-height:0;overflow:hidden;mso-hide:all;">${escapeEmailHtml(preheader)}</div>
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#f4f3f8;"><tr><td align="center" style="padding:32px 12px;">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="max-width:${safeWidth}px;background-color:#ffffff;border:1px solid #e4e4e7;border-radius:16px;overflow:hidden;">
      <tr><td style="padding:28px 24px;background-color:#302043;border-radius:16px 16px 0 0;">
        <img src="cid:congregacao-logo" alt="Congregação Praia dos Corais" width="88" height="88" style="display:block;width:88px;height:88px;margin:0 0 18px;border:0;" />
        <p style="margin:0 0 8px;font-size:12px;font-weight:bold;letter-spacing:2px;color:#d8b4fe;">PRAIA DOS CORAIS</p>
        <p style="margin:0;font-size:20px;font-weight:bold;color:#ffffff;">Controle de Publicadores</p>
      </td></tr>
      <tr><td style="padding:28px 24px;">
        <p style="margin:0 0 12px;font-size:12px;font-weight:bold;letter-spacing:1px;color:#7e22ce;">${escapeEmailHtml(label)}</p>
        <h1 style="margin:0 0 24px;font-size:28px;line-height:36px;color:#18181b;">${escapeEmailHtml(title)}</h1>
        ${content}
      </td></tr>
      <tr><td style="padding:24px;border-top:1px solid #e4e4e7;background-color:#fafafa;border-radius:0 0 16px 16px;">
        <p style="margin:0 0 6px;font-size:13px;font-weight:bold;color:#52525b;">Congregação Praia dos Corais</p>
        <p style="margin:0;font-size:12px;line-height:20px;color:#71717a;">Mensagem automática do Controle de Publicadores.${footerNote ? `<br>${escapeEmailHtml(footerNote)}` : ''}</p>
      </td></tr>
    </table>
  </td></tr></table>
</body></html>`;
}

export function brandEmailText(content) {
  return `PRAIA DOS CORAIS\nControle de Publicadores\n\n${content}\n\nCongregação Praia dos Corais\nMensagem automática do Controle de Publicadores.`;
}
